function tick(g) {
  const p = g.p;
  if (g.keys.left) p.x -= 3;
  if (g.keys.right) p.x += 3;
  p.vy += 0.5;
  p.y += p.vy;
  if (p.y + p.h > 300) {
    p.y = 300 - p.h;
    p.vy = 0;
  }
  if (p.iframes > 0) p.iframes--;
  g.coins = g.coins.filter(c => {
    if (overlaps(p, c)) {
      g.score++;
      return false;
    }
    return true;
  });
  if (p.iframes === 0 && g.enemies.some(e => overlaps(p, e))) {
    g.lives--;
    p.iframes = 60;
  }
  return g;
}

